<div class="split-layout"><section class="stack"><?php foreach($list as $a): ?><article class="card announcement-detail" id="announcement-<?= e($a['id']) ?>"><div class="meta"><span class="badge company"><?= e($a['ten_phong_ban']??'Toàn công ty') ?></span><time><?= e($a['ngay_tao']) ?></time></div><h2><?= e($a['tieu_de']) ?></h2><div class="prose"><?= nl2br(e($a['noi_dung'])) ?></div><div class="article-footer"><span><?= e($a['ho_ten']) ?></span><?php if($canEdit): ?><div class="actions"><a class="button subtle" href="/announcements?edit=<?= e($a['id']) ?>#announcement-form">Sửa</a><form method="post" class="confirm-delete"><?php csrf_field() ?><input type="hidden" name="id" value="<?= e($a['id']) ?>"><input type="hidden" name="action" value="delete"><button id="delete-announcement-<?= e($a['id']) ?>" class="button danger">Xóa</button></form></div><?php endif ?></div></article><?php endforeach ?><?php if(!$list): ?><div class="card empty">Chưa có thông báo dành cho bạn.</div><?php endif ?></section><?php if($canEdit): ?><section class="card form-card" id="announcement-form"><h2><?= $edit?'Sửa thông báo':'Đăng thông báo' ?></h2><p class="muted">Chia sẻ cập nhật với đội ngũ.</p><form method="post" class="form-stack"><?php csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><?php endif ?><?php field('tieu_de','Tiêu đề',$edit['tieu_de']??''); textarea_field('noi_dung','Nội dung',$edit['noi_dung']??''); select_field('pham_vi','Phạm vi',['company'=>'Toàn công ty','department'=>'Theo phòng ban'],$edit['pham_vi']??'company'); select_field('phong_ban_id','Phòng ban (khi chọn phạm vi phòng ban)',array_column(departments(),'ten_phong_ban','id'),$edit['phong_ban_id']??''); ?><button id="save-announcement" class="button"><?= $edit?'Lưu thay đổi':'Đăng thông báo' ?></button><?php if($edit): ?><a href="/announcements" class="text-link">Hủy chỉnh sửa</a><?php endif ?></form></section><?php endif ?></div>
